from binkeep import journal
from binkeep.bins import normalize
from binkeep.context import Context
from binkeep.errors import DataError, Refused

STOCK_OPS = journal.OPS


class Stacks:
    """The *done* and *undone* stacks, worked out from the journal (undo.md, section 2)."""

    def __init__(self):
        self.operations: list[dict] = []   # every operation line, in file order
        self.done: list[dict] = []
        self.undone: list[dict] = []
        self.dropped: set[int] = set()     # id() of dropped operation lines
        self.last_undo: dict[int, dict] = {}

    @classmethod
    def read(cls, entries: list[dict]) -> "Stacks":
        s = cls()
        for e in entries:
            s.apply(e)
        return s

    def apply(self, e: dict) -> None:
        op = e["op"]
        if op in STOCK_OPS:
            self.operations.append(e)
            self.done.append(e)
            self.dropped.update(id(x) for x in self.undone)
            self.undone.clear()
        elif op in ("undo", "redo"):
            src, dst = (self.done, self.undone) if op == "undo" else (self.undone, self.done)
            target = e.get("target")
            if not src or type(target) is not int or src[-1]["seq"] != target:
                raise DataError("journal", f"line {e['seq']}: {op} does not match the stacks")
            dst.append(src.pop())
            if op == "undo":
                self.last_undo[target] = e

    def status(self, e: dict) -> str:
        if id(e) in self.dropped:
            return "dropped"
        if any(x is e for x in self.undone):
            return "undone"
        return "barrier" if e["op"] == "fix" else "done"


def _effects(e: dict) -> list[tuple[str, int]]:
    """(bin, before) of a format 2 line, validated."""
    eff = e.get("effects")
    if not isinstance(eff, list):
        raise DataError("journal", f"line {e['seq']}: no effects")
    out = []
    for x in eff:
        if (not isinstance(x, dict) or not isinstance(x.get("bin"), str)
                or not isinstance(x.get("before"), int) or isinstance(x.get("before"), bool)):
            raise DataError("journal", f"line {e['seq']}: bad effects")
        out.append((normalize(x["bin"]), x["before"]))
    return out


def _int(e: dict, key: str) -> int:
    v = e.get(key)
    if not isinstance(v, int) or isinstance(v, bool):
        raise DataError("journal", f"line {e['seq']}: bad {key}")
    return v


def _str(e: dict, key: str) -> str:
    v = e.get(key)
    if not isinstance(v, str):
        raise DataError("journal", f"line {e['seq']}: bad {key}")
    return v


def _format1_deltas(ctx: Context, e: dict) -> list[tuple[str, int]]:
    """The changes that take back a format 1 operation, last change first."""
    op = e["op"]
    if op == "receive":
        qty = _int(e, "qty")
        if e.get("uom") == "pk":
            sku = _str(e, "sku")
            if sku not in ctx.items:
                raise Refused("unknown-sku", f"no item {sku}")
            qty *= ctx.items[sku].pack_size
        return [(normalize(_str(e, "bin")), -qty)]
    if op == "issue":
        picks = e.get("picks")
        if not isinstance(picks, list):
            raise DataError("journal", f"line {e['seq']}: bad picks")
        out = []
        for p in picks:
            if (not isinstance(p, (list, tuple)) or len(p) != 2 or not isinstance(p[0], str)
                    or not isinstance(p[1], int) or isinstance(p[1], bool)):
                raise DataError("journal", f"line {e['seq']}: bad picks")
            out.append((normalize(p[0]), p[1]))
        return out[::-1]
    if op == "move":
        qty = _int(e, "qty")
        return [(normalize(_str(e, "to")), -qty), (normalize(_str(e, "from")), qty)]
    raise DataError("journal", f"line {e['seq']}: cannot be reversed")


def _check_bins(ctx: Context, codes) -> None:
    for code in codes:
        if code not in ctx.bins:
            raise Refused("unknown-bin", f"no bin {code}")


def _restore(store, sku: str, sets: list[tuple[str, int]], effects: list) -> None:
    """Sets bins one after another, whatever their status (undo.md, section 4)."""
    for code, qty in sets:
        before = store.qty(sku, code)
        store.restore(sku, code, qty)
        effects.append({"bin": code, "before": before, "after": qty})


def _step(ctx: Context, stacks: Stacks, store, seq: int, kind: str):
    """One undo or redo step. Returns the new journal line; changes store and stacks."""
    if kind == "undo":
        if not stacks.done:
            raise Refused("nothing-to-undo", "nothing to undo")
        op = stacks.done[-1]
        if op["op"] == "fix":
            raise Refused("barrier", "a fix cannot be undone")
        if op.get("v") == 2:
            sets = [(c, b) for c, b in _effects(op)[::-1]]
            sets_fn = None
        else:
            if op["op"] == "count":
                raise Refused("irreversible", "a format 1 count cannot be undone")
            deltas = _format1_deltas(ctx, op)
            sets_fn = deltas
            sets = None
    else:
        if not stacks.undone:
            raise Refused("nothing-to-redo", "nothing to redo")
        op = stacks.undone[-1]
        undo_line = stacks.last_undo.get(op["seq"])
        if undo_line is None:
            raise DataError("journal", f"line {op['seq']}: no undo line")
        sets = _effects(undo_line)[::-1]
        sets_fn = None
    sku = _str(op, "sku")
    codes = [c for c, _ in (sets if sets is not None else sets_fn)]
    _check_bins(ctx, codes)
    if sets is None:
        sets = []
        probe = store.copy()
        for code, delta in sets_fn:
            new = probe.qty(sku, code) + delta
            if new < 0:
                raise DataError("journal", f"{sku} in {code} would go below zero")
            probe.restore(sku, code, new)
            sets.append((code, new))
    effects: list = []
    _restore(store, sku, sets, effects)
    line = journal.entry(seq, kind, ctx.by, sku, target=op["seq"], effects=effects)
    stacks.apply(line)
    return line


def run(ctx: Context, kind: str, steps: int):
    stacks = Stacks.read(ctx.entries)
    store = ctx.store.copy()
    seq = journal.next_seq(ctx.entries)
    lines = []
    out: list[str] = []
    for _ in range(steps):
        target_op = (stacks.done[-1] if kind == "undo" else stacks.undone[-1]) if (
            stacks.done if kind == "undo" else stacks.undone) else None
        line = _step(ctx, stacks, store, seq, kind)
        seq += 1
        lines.append(line)
        out.append(f"#{line['seq']} {kind} {line['sku']} (#{line['target']} {target_op['op']})")
        out.extend(f"  {e['bin']} {e['before']} -> {e['after']}" for e in line["effects"])
    ctx.commit(store, lines)
    return out


def history(ctx: Context, limit: int) -> list[str]:
    stacks = Stacks.read(ctx.entries)
    return [f"{e['seq']:>5}  {e['op']:<7}  {e.get('sku', ''):<10}  {stacks.status(e)}"
            for e in stacks.operations[::-1][:limit]]
