def _is_int(v) -> bool:
    return isinstance(v, int) and not isinstance(v, bool)


def _effects(e: dict) -> list[tuple[str, int]]:
    """(bin, before) of a format 2 line, validated."""
    eff = e.get("effects")
    if not isinstance(eff, list):
        raise DataError("journal", f"line {e['seq']}: no effects")
