    for x in eff:
        if not isinstance(x, dict) or not isinstance(x.get("bin"), str) or not _is_int(x.get("before")):
            raise DataError("journal", f"line {e['seq']}: bad effects")
        out.append((normalize(x["bin"]), x["before"]))
    return out


def _int(e: dict, key: str) -> int:
    v = e.get(key)
    if not _is_int(v):
        raise DataError("journal", f"line {e['seq']}: bad {key}")
    return v


def _str(e: dict, key: str) -> str:
    v = e.get(key)
    if not isinstance(v, str):
        raise DataError("journal", f"line {e['seq']}: bad {key}")
    return v


def _format1_deltas(ctx: Context, e: dict) -> list[tuple[str, int]]:
    """The changes that take back a format 1 operation, last change first."""
    op = e["op"]
    if op == "receive":
        qty = _int(e, "qty")
        if e.get("uom") == "pk":
