        if deltas is None:
            code, new = sets[i]
        else:
            code, delta = deltas[i]
            new = store.qty(sku, code) + delta
        before = store.qty(sku, code)
        store.restore(sku, code, new)
        effects.append({"bin": code, "before": before, "after": new})
